def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    paths = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                # Move two cells right, then one cell up.
                path = [(r, x) for x in range(c, c + 3)]
                path += [(r - 1, c + 2)]
            elif color == 2:
                path = [(r, x) for x in range(c, c - 5, -1)]
            elif color == 3:
                path = [(x, c) for x in range(r, r + 4)]
            elif color == 6:
                path = [(x, c) for x in range(r, r - 7, -1)]
            else:
                continue
            path = [(y, x) for y, x in path if 0 <= y < h and 0 <= x < w]
            paths.append((color, (r, c), path))

    for color, origin, path in paths:
        for r, c in path:
            if (r, c) != origin and out[r][c] == 0:
                out[r][c] = 5

    # Intersecting trails create a diagonal trail of color 4.
    intersections = set()
    for i in range(len(paths)):
        for j in range(i + 1, len(paths)):
            a = set(paths[i][2])
            b = set(paths[j][2])
            intersections.update(a & b)

    for r, c in intersections:
        for k in range(min(h - 1 - r, c) + 1):
            out[r + k][c - k] = 4

    # Preserve the original markers and mark each trail's endpoint.
    for color, origin, path in paths:
        out[origin[0]][origin[1]] = color
        if path:
            er, ec = path[-1]
            if (er, ec) != origin and (er, ec) not in intersections:
                out[er][ec] = color

    return out
